  "settings.modelProvider.fieldHelp": "О поле {field}",
  "settings.modelProvider.help.contextWindow": "Объём контекста, который модель может обработать за раз, в токенах. ZAICODE использует его для управления контекстом.\nНе превышайте реальный лимит модели.",
  "settings.modelProvider.help.maxOutputTokens": "Максимальное число токенов, которое модель может сгенерировать в одном запросе.\nНе превышайте реальный лимит модели.",
  "settings.modelProvider.help.inputModalities": "Задайте типы содержимого, которые модель может получать:\n\n- **Текст**: получает текстовое содержимое. Обязательно.\n- **Изображения**: получает изображения.\n- **Видео**: получает видео.\n- **PDF**: получает документы PDF напрямую.",
  "settings.modelProvider.help.outputModalities": "Тип содержимого ответов модели. Сейчас поддерживается только текст.",
  "settings.modelProvider.help.capabilities": "- **Структурированный вывод**: поддерживает ограничения JSON Schema на поля, типы и структуру вывода.\n- **Встроенный веб-поиск**: поддерживает встроенную возможность веб-поиска API модели.\n- **Системные сообщения посреди беседы**: поддерживает вставку системных инструкций во время беседы.\n\nНе включайте возможности, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Задайте уровни рассуждения, доступные в чате. **Они должны идти от наименьшего усилия рассуждения к наибольшему**.\nНе настраивайте уровни рассуждения, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelMapping": "Используйте выражение CEL, чтобы сопоставить текущий уровень рассуждения `reasoningLevel` с полями запроса к API модели. JSON-объект, возвращённый выражением, объединяется с телом исходящего запроса.",
  "settings.modelProvider.help.advanced": "**Схема инструментов MFJS**: включает совместимость с Moonshot Flavored JSON Schema, которую обычно использует API модели Kimi от Moonshot. Включайте, только если API модели требует этот формат.",
  "settings.modelProvider.help.followRecommendedConfig": "Подбирает рекомендуемую конфигурацию по ID модели, базовому URL и формату API. ZAICODE постоянно обновляет рекомендации и автоматически синхронизирует их с вами.\nКогда вы вручную меняете параметр, он переходит на ручное управление и перестаёт следовать обновлениям рекомендаций; остальные параметры остаются под управлением умной настройки.",
  "settings.modelProvider.modelDefaultsLoaded": "Для этой модели подобрана умная настройка",
